class TicketStore:
    """票据缓存：自签发起 ttl 秒有效，读取不续期。过期返回 None。"""

    def __init__(self, ttl):
        self.ttl = ttl
        self._items = {}

    def issue(self, token, now):
        self._items[token] = now

    def check(self, token, now):
        if token not in self._items:
            return False
        issued = self._items[token]
        if now - issued >= self.ttl:
            return False
        self._items[token] = now
        return True
